function findFirstBad(items, isGood) {
  let lo = 0, hi = items.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (isGood(items[mid])) lo = mid + 1
    else hi = mid
  }
  return lo === items.length ? -1 : lo
}
